css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .rig { position: absolute; left: 33%; top: 4%; width: 34%; height: 74%; animation: jack-buck calc(var(--loader-speed) * .22) ease-in-out infinite; }
.loader .grip { position: absolute; left: -18%; top: 0; width: 136%; height: 12%; border-radius: 5px; background: var(--accent-2); }
.loader .barrel { position: absolute; left: 16%; top: 10%; width: 68%; height: 62%; border-radius: 6px; background: linear-gradient(90deg, var(--accent), color-mix(in srgb, #000 22%, var(--accent))); }
.loader .bit { position: absolute; left: 38%; top: 70%; width: 24%; height: 32%; border-radius: 2px; background: linear-gradient(#cbd5e1, #64748b); }
.loader .slab { position: absolute; left: 6%; right: 6%; bottom: 4%; height: 16%; border-radius: 4px; background: repeating-linear-gradient(90deg, var(--accent-2) 0 18%, color-mix(in srgb, #000 18%, var(--accent-2)) 0 20%); animation: jack-shake calc(var(--loader-speed) * .22) ease-in-out infinite; }
.loader i { position: absolute; bottom: 18%; width: 7%; height: 6%; border-radius: 2px; background: var(--accent-2); opacity: 0; animation: jack-chip calc(var(--loader-speed) * .88) ease-out infinite; }
.loader i:nth-of-type(1) { left: 30%; --dx: -150%; }
.loader i:nth-of-type(2) { left: 47%; --dx: 20%; animation-delay: calc(var(--loader-speed) * .3); }
.loader i:nth-of-type(3) { left: 62%; --dx: 160%; animation-delay: calc(var(--loader-speed) * .6); }
@keyframes jack-buck { 0%, 100% { transform: translateY(0); } 50% { transform: translateY(5%); } }
@keyframes jack-shake { 0%, 100% { transform: translateX(0); } 50% { transform: translateX(1.5%); } }
@keyframes jack-chip { 0% { opacity: 0; transform: translate(0, 0) rotate(0deg); } 15% { opacity: 1; } 100% { opacity: 0; transform: translate(var(--dx, 0%), -180%) rotate(200deg); } }
